36	     * the region component that precedes the first {@code '-'}. Owners without a customer code (for
37	     * example seed data that predates identity assignment) fall back to
38	     * {@link #forPostcodeAndCity(String, String)}.
39	     *
40	     * @param customerCode the owner's region-and-hash customer code, or {@code null}
41	     * @param postcode the owner's stored postcode, or {@code null} (used only for the fallback)
42	     * @param city the owner's stored city, or {@code null} (used only for the fallback)
43	     * @return the region component of the customer code, or the postcode-and-city fallback
44	     */
45	    public static String forCustomerCode(String customerCode, String postcode, String city) {
46	        if (customerCode != null) {
47	            int separator = customerCode.indexOf('-');
48	            if (separator > 0) {
49	                return customerCode.substring(0, separator);
