282	    }
283	
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner != null) {
290	            Pet pet = owner.getPet(petId);
291	            if (pet != null) {
292	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
293	            }
294	        }
295	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
296	    }
297	
298	    /**
299	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
300	     * offending field is collected so the caller learns exactly which values must be supplied.
301	     *
302	     * @param ownerFieldsDto the submitted owner payload
303	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
304	     *         telephone is missing or blank
305	     */
306	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
307	        List<String> missingFields = new ArrayList<>();
308	        if (isBlank(ownerFieldsDto.getFirstName())) {
309	            missingFields.add("firstName");
310	        }
311	        if (isBlank(ownerFieldsDto.getLastName())) {
312	            missingFields.add("lastName");
313	        }
314	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
315	            missingFields.add("address");
316	        }
317	        if (isBlank(ownerFieldsDto.getCity())) {
318	            missingFields.add("city");
319	        }
320	        if (isBlank(ownerFieldsDto.getTelephone())) {
321	            missingFields.add("telephone");
322	        }
323	        if (!missingFields.isEmpty()) {
324	            throw new MissingOwnerFieldsException(missingFields);
325	        }
326	    }
327	
328	    private boolean isBlank(String value) {
329	        return value == null || value.isBlank();
330	    }
331	
332	    /**
333	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
334	     * current date. A registration date may not lie in the future; a value equal to today or in the
335	     * past is accepted, and an absent date is left to default to the server date.
336	     *
337	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
338	     * @throws InvalidOwnerFieldsException if the supplied date is after the server's current date
339	     */
340	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
341	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
342	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
343	        }
344	    }
345	
346	    /**
347	     * Counts the existing owners who, before this create, already share the given first and last name.
348	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
349	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
350	     * case or spacing still count as the same name.
351	     *
352	     * @param firstName the first name of the owner being created
353	     * @param lastName the last name of the owner being created
354	     * @return the number of existing owners sharing both names (zero when none)
355	     */
356	    private int countNamesakes(String firstName, String lastName) {
357	        String first = normalizeHouseholdField(firstName);
358	        String last = normalizeHouseholdField(lastName);
359	        return (int) this.clinicService.findAllOwners().stream()
360	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
361	                && normalizeHouseholdField(existing.getLastName()).equals(last))
362	            .count();
363	    }
364	
365	    /**
366	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
367	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
368	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
369	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
370	     * more owners the create is rejected as a conflict.
371	     *
372	     * @param city the city of the owner being created
373	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
374	     */
375	    /**
376	     * Rejects an owner create once the maximum number of owners have already been registered on the
377	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
378	     * which is always a business day (a weekend effective date is rolled forward to the following
379	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
380	     * business day the create is rejected as too many requests. Because a weekend effective date is
381	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
382	     *
383	     * @param businessDay the adjusted business day the owner being created would be registered on
384	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
385	     */
386	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
387	        long ownersOnDay = this.clinicService.findAllOwners().stream()
388	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
389	            .count();
390	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
391	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
392	        }
393	    }
394	
395	    /**
396	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
397	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
398	     * was supplied on the request or defaulted to the server's current date.
399	     *
400	     * @param date the effective registration date (supplied or defaulted)
401	     * @return the same date when it is a weekday, otherwise the following Monday
402	     */
403	    /**
404	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
405	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
406	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
407	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
408	     *
409	     * @return {@code true} when more than the threshold number of owners are already registered on
410	     *         today's business day, otherwise {@code false}
411	     */
412	    private boolean isBulkSignupWarningActive() {
413	        LocalDate today = toBusinessDay(LocalDate.now());
414	        long ownersToday = this.clinicService.findAllOwners().stream()
415	            .filter(existing -> today.equals(existing.getRegistrationDate()))
416	            .count();
417	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
418	    }
419	
420	    private LocalDate toBusinessDay(LocalDate date) {
421	        return switch (date.getDayOfWeek()) {
422	            case SATURDAY -> date.plusDays(2);
423	            case SUNDAY -> date.plusDays(1);
424	            default -> date;
425	        };
426	    }
427	
428	    private void rejectCityAtCapacity(String city) {
429	        String normalizedCity = normalizeHouseholdField(city);
430	        long ownersInCity = this.clinicService.findAllOwners().stream()
431	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
432	            .count();
433	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
434	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
435	        }
436	    }
437	
438	    /**
439	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
440	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
441	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
442	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
443	     * to the same base code only when they share a region and produce the same telephone-and-last-name
444	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
445	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
446	     *
447	     * @param postcode the owner's postcode, used first to derive the region
448	     * @param city the owner's city, used to derive the region when the postcode maps to none
449	     * @param normalizedTelephone the owner's normalized (E.164) telephone
450	     * @param lastName the owner's last name
451	     * @return the formatted, de-duplicated customer code
452	     */
453	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
454	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
455	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
456	        String baseCode = region + "-" + hash8;
457	        return deduplicateCustomerCode(baseCode);
458	    }
459	
460	    /**
461	     * De-duplicates a computed customer code against every existing owner's customer code. When no
462	     * existing owner already carries the base code it is returned unchanged; otherwise '-&lt;n&gt;' is
463	     * appended with the smallest {@code n} of 2 or more that yields a code no existing owner holds.
464	     *
465	     * @param baseCode the computed, formatted customer code before de-duplication
466	     * @return the base code when unique, otherwise the base code suffixed with '-&lt;n&gt;'
467	     */
468	    private String deduplicateCustomerCode(String baseCode) {
469	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
470	            .map(Owner::getCustomerCode)
471	            .filter(java.util.Objects::nonNull)
472	            .collect(java.util.stream.Collectors.toSet());
473	        if (!existingCodes.contains(baseCode)) {
474	            return baseCode;
475	        }
476	        int n = 2;
477	        while (existingCodes.contains(baseCode + "-" + n)) {
478	            n++;
479	        }
480	        return baseCode + "-" + n;
481	    }
482	
483	    /**
484	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
485	     * customerCode is the owner's customer code and YY is the last two digits of the
486	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
487	     *
488	     * @param customerCode the owner's customer code
489	     * @param registrationDate the owner's registration date
490	     * @return the formatted membership number
491	     */
492	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
493	        String yy = String.format("%02d", registrationDate.getYear() % 100);
494	        return customerCode + "-M" + yy;
495	    }
496	
497	    /**
498	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
499	     * country calling code. Australia ('+61') uses 9 national digits and the North American
500	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
501	     * E.164 length (8 to 15 digits overall).
502	     */
503	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
504	        java.util.Map.of("61", 9, "1", 10);
505	
506	    /**
507	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
508	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
509	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
510	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
511	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
512	     * E.164 string is what gets stored and returned.
513	     *
514	     * @param telephone the raw telephone value from the request
515	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
516	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
517	     *         national number has the wrong length for its country code
518	     */
519	    private String normalizeTelephone(String telephone) {
520	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
521	        String e164;
522	        if (cleaned.startsWith("+")) {
523	            e164 = cleaned;
524	        } else {
525	            String national = cleaned;
526	            if (national.startsWith("0")) {
527	                national = national.substring(1);
528	            }
529	            e164 = "+61" + national;
530	        }
531	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
532	            throw new InvalidOwnerFieldsException(List.of("telephone"));
533	        }
534	        validateNationalNumberLength(e164);
535	        return e164;
536	    }
537	
538	    /**
539	     * Rejects an E.164 telephone whose national number does not have the exact length its country
540	     * calling code requires. The digits after the leading '+' are split into the longest matching
541	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
542	     * code is known and the national number's length differs from the required count the telephone is
543	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
544	     *
545	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
546	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
547	     */
548	    private void validateNationalNumberLength(String e164) {
549	        String digits = e164.substring(1);
550	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
551	            String countryCode = digits.substring(0, codeLength);
552	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
553	            if (requiredNationalLength != null) {
554	                int nationalLength = digits.length() - codeLength;
555	                if (nationalLength != requiredNationalLength) {
556	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
557	                }
558	                return;
559	            }
560	        }
561	    }
562	
563	    /**
564	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
565	     * left unset. When a value is present it must be a syntactically valid address whose domain is not
566	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the normalized form
567	     * stored and returned is the value lower-cased.
568	     *
569	     * @param email the raw email value from the request, or {@code null} when none was supplied
570	     * @return the lower-cased email, or {@code null} when no email was supplied
571	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address or
572	     *         its domain is on the disposable-domain blocklist
573	     */
574	    private String normalizeEmail(String email) {
575	        if (email == null || email.isBlank()) {
576	            return null;
577	        }
578	        if (!EMAIL_PATTERN.matcher(email).matches()) {
579	            throw new InvalidOwnerFieldsException(List.of("email"));
580	        }
581	        String normalized = email.toLowerCase(Locale.ROOT);
582	        String domain = normalized.substring(normalized.indexOf('@') + 1);
583	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
584	            throw new InvalidOwnerFieldsException(List.of("email"));
585	        }
586	        return normalized;
587	    }
588	
589	    /**
590	     * Validates an optional postcode supplied on create. A postcode is validated only when present:
591	     * an absent (null or blank) postcode is accepted, keeping the create request backward-compatible.
592	     * When present it must be exactly four digits and, when the owner's city maps to a known region
593	     * (see {@link LocalityLookup}), must fall within that region's inclusive range
594	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
595	     * region accepts any four-digit postcode.
596	     *
597	     * @param city the owner's city, used to derive the region whose range the postcode must satisfy
598	     * @param postcode the raw postcode value from the request, or {@code null} when none was supplied
599	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
600	     *         for the city's region
601	     */
602	    private void validatePostcode(String city, String postcode) {
603	        if (postcode == null || postcode.isBlank()) {
604	            return;
605	        }
606	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
607	            throw new InvalidOwnerFieldsException(List.of("postcode"));
608	        }
609	        int[] range = REGION_POSTCODE_RANGES.get(LocalityLookup.forCity(city));
610	        if (range == null) {
611	            return;
612	        }
613	        int value = Integer.parseInt(postcode);
614	        if (value < range[0] || value > range[1]) {
615	            throw new InvalidOwnerFieldsException(List.of("postcode"));
616	        }
617	    }
618	
619	    /**
620	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
621	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
622	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
623	     * normalized form is what gets stored, returned and used for every address comparison (the
624	     * required-field check, household duplicate detection and the shared household id).
625	     *
626	     * @param address the raw address value from the request, or {@code null}
627	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
628	     */
629	    private String normalizeAddress(String address) {
630	        if (address == null) {
631	            return "";
632	        }
633	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
634	        if (collapsed.isEmpty()) {
635	            return "";
636	        }
637	        String[] tokens = collapsed.split(" ");
638	        for (int i = 0; i < tokens.length; i++) {
639	            switch (tokens[i]) {
640	                case "ST" -> tokens[i] = "STREET";
641	                case "RD" -> tokens[i] = "ROAD";
642	                case "AVE" -> tokens[i] = "AVENUE";
643	                default -> { }
644	            }
645	        }
646	        return String.join(" ", tokens);
647	    }
648	
649	    /**
650	     * Rejects an owner create whose {@code identityKey} exactly matches an existing owner's. The
651	     * identity key - the owner's normalized telephone, email (empty when none) and {@code householdId}
652	     * (empty when none) joined by {@code '|'} - is the single derived value that subsumes the former
653	     * separate telephone, email and household duplicate checks. Only a whole-key match is a conflict,
654	     * so two members of one household with different telephones have different keys and are both
655	     * allowed; only an owner whose entire key is identical is a duplicate.
656	     *
657	     * @param owner the owner being created, with its telephone, email and householdId already resolved
658	     * @throws DuplicateOwnerIdentityException if another owner already has this exact identity key
659	     */
660	    private void rejectDuplicateIdentity(Owner owner) {
661	        String identityKey = owner.getIdentityKey();
662	        boolean inUse = this.clinicService.findAllOwners().stream()
663	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
664	        if (inUse) {
665	            throw new DuplicateOwnerIdentityException(identityKey);
666	        }
667	    }
668	
669	    /**
670	     * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
671	     * that shares this owner's last name (compared case-insensitively with collapsed whitespace) and
672	     * postcode but carries a different (normalized) telephone; such an owner is not a hard duplicate
673	     * (its identity key differs) and is still created. When at least one soft match exists,
674	     * {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the lowest-id match;
675	     * otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left unset.
676	     * <p>
677	     * A declared household member - an owner that acknowledged sharing an existing household via
678	     * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
679	     * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
680	     *
681	     * @param owner the owner being created, with its last name, postcode and normalized telephone resolved
682	     * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
683	     */
684	    private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
685	        if (declaredHouseholdMember) {
686	            owner.setPossibleDuplicate(false);
687	            return;
688	        }
689	        String lastName = normalizeHouseholdField(owner.getLastName());
690	        String postcode = owner.getPostcode();
691	        String telephone = owner.getTelephone();
692	        Owner match = null;
693	        if (postcode != null && !postcode.isBlank()) {
694	            match = this.clinicService.findAllOwners().stream()
695	                .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName))
696	                .filter(existing -> postcode.equals(existing.getPostcode()))
697	                .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
698	                .min(java.util.Comparator.comparing(Owner::getId))
699	                .orElse(null);
700	        }
701	        if (match != null) {
702	            owner.setPossibleDuplicate(true);
703	            owner.setPossibleDuplicateOf(match.getId());
704	        } else {
705	            owner.setPossibleDuplicate(false);
706	        }
707	    }
708	
709	    /**
710	     * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
711	     * household member count} for the response.
712	     *
713	     * @param owner the owner to map
714	     * @return the mapped owner DTO
715	     */
716	    private OwnerDto toOwnerDto(Owner owner) {
717	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
718	        return ownerMapper.toOwnerDto(owner);
719	    }
720	
721	    /**
722	     * Counts the members of the given owner's household - the owners that share this owner's
723	     * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
724	     * is {@code null}) is its own sole member, so the count is one.
725	     *
726	     * @param owner the owner whose household is being sized
727	     * @return the number of owners sharing this owner's household (one when it has no household)
728	     */
729	    private int countHouseholdMembers(Owner owner) {
730	        String householdId = owner.getHouseholdId();
731	        if (householdId == null) {
732	            return 1;
733	        }
734	        return (int) this.clinicService.findAllOwners().stream()
735	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
736	            .count();
737	    }
738	
739	    /**
740	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
741	     * last name and a postcode: the {@code householdId} is derived deterministically from the
742	     * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
743	     * owners with the same last name and postcode always resolve to the same identifier and belong to
744	     * the same household automatically - no acknowledgement is needed to create the link.
745	     * <p>
746	     * When the owner supplies a postcode its {@code householdId} is always assigned. If that household
747	     * already has at least one member, the create is a household duplicate: it is rejected with a 409
748	     * unless {@code sharesHousehold} is true, in which case the owner is created as a declared member
749	     * of that household. An owner with no postcode belongs to no household and is left without an
750	     * identifier.
751	     *
752	     * @param owner the owner being created
753	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
754	     * @return {@code true} when the owner joined an existing household as a declared member, otherwise
755	     *         {@code false}
756	     * @throws DuplicateOwnerHouseholdException when the household already exists and the create did not
757	     *         acknowledge it via {@code sharesHousehold}
758	     */
759	    private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
760	        String postcode = owner.getPostcode();
761	        if (postcode == null || postcode.isBlank()) {
762	            return false;
763	        }
764	        String lastName = normalizeHouseholdField(owner.getLastName());
765	        String householdId = generateHouseholdId(lastName, postcode);
766	        owner.setHouseholdId(householdId);
767	        boolean hasExistingMember = this.clinicService.findAllOwners().stream()
768	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
769	        if (!hasExistingMember) {
770	            return false;
771	        }
772	        if (!Boolean.TRUE.equals(sharesHousehold)) {
773	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), postcode);
774	        }
775	        return true;
776	    }
777	
778	    /**
779	     * Builds the stable identifier shared by the members of one household. It is derived purely from
780	     * the normalized last name and the postcode, so every owner sharing a last name and postcode
781	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
782	     * two fields joined by a single '|'.
783	     *
784	     * @param normalizedLastName the household's last name, already normalized for comparison
785	     * @param postcode the household's postcode
786	     * @return the shared household identifier
787	     */
788	    private String generateHouseholdId(String normalizedLastName, String postcode) {
789	        String key = normalizedLastName + '|' + postcode;
790	        try {
791	            byte[] digest = MessageDigest.getInstance("SHA-256")
792	                .digest(key.getBytes(StandardCharsets.UTF_8));
793	            StringBuilder hex = new StringBuilder();
794	            for (byte b : digest) {
795	                hex.append(String.format("%02X", b));
796	                if (hex.length() >= 12) {
797	                    break;
798	                }
799	            }
800	            return hex.substring(0, 12);
801	        } catch (NoSuchAlgorithmException e) {
802	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
803	        }
804	    }
805	
806	    /**
807	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the given
808	     * input's UTF-8 bytes. Used to derive the customer code's stable, deterministic hash component from
809	     * the owner's normalized telephone and last name.
810	     *
811	     * @param input the string to digest
812	     * @param length the number of leading upper-case hex characters to return
813	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
814	     */
815	    private String sha256UpperHex(String input, int length) {
816	        try {
817	            byte[] digest = MessageDigest.getInstance("SHA-256")
818	                .digest(input.getBytes(StandardCharsets.UTF_8));
819	            StringBuilder hex = new StringBuilder();
820	            for (byte b : digest) {
821	                hex.append(String.format("%02X", b));
822	                if (hex.length() >= length) {
823	                    break;
824	                }
825	            }
826	            return hex.substring(0, length);
827	        } catch (NoSuchAlgorithmException e) {
828	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
829	        }
830	    }
831	
832	    /**
833	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
834	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
835	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
836	     * expands common abbreviations.
837	     *
838	     * @param value the raw last name, or {@code null}
839	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
840	     */
841	    private String normalizeHouseholdField(String value) {
842	        if (value == null) {
843	            return "";
844	        }
845	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
846	    }
847	}
